function registerHotInputElements(){for(var a=document.querySelectorAll("input[improve-input]"),b=0;b<a.length;b++)a[b].addEventListener("input",function(c){onChangeInputValue(this)})}function onChangeInputValue(a){var b=a.value;a.hasAttribute("rm-white-spaces")&&(b=b.split(" ").join("")),a.hasAttribute("to-lower")&&(b=b.toLowerCase()),a.hasAttribute("to-upper")&&(b=b.toUpperCase()),a.hasAttribute("to-arabic-numbers")&&(b=toArabicNumbers(b)),a.hasAttribute("only-numbers")&&(b=b.replace(/\D/g,"")),a.hasAttribute("no-numbers")&&(b=b.replace(/[0-9]/g,"")),a.hasAttribute("only-alphanumeric")&&(b=b.replace(/[^0-9a-z]/gi,"")),a.hasAttribute("to-tel-type-when")&&toTelTypeWhen(a,b),a.value=b}function toArabicNumbers(a){var map={":":"0","٠":"0","١":"1","٢":"2","٣":"3","٤":"4","٥":"5","٦":"6","٧":"7","٨":"8","٩":"9"};return a.replace(/[:\u0660-\u0669]/g,function(c){return map[c]})}function toTelTypeWhen(a,b){var c=a.getAttribute("to-tel-type-when");null!=c&&""!==c&&(b.length<parseInt(c)?a.setAttribute("type","text"):a.setAttribute("type","tel"))}document.addEventListener("DOMContentLoaded",function(){registerHotInputElements()},!1);